module fifo_04 (
  input wr_clk,
  input wr_rst_n,
  input wr_en,
  input [7:0] wr_data,
  input rd_clk,
  input rd_rst_n,
  input rd_en,
  output [7:0] rd_data,
  output full,
  output empty
);

  // FIFO parameters
  localparam DEPTH = 4;
  localparam ADDR_WIDTH = 2;

  // Storage array
  reg [7:0] fifo_mem [0:DEPTH-1];

  // Write side
  reg [ADDR_WIDTH-1:0] wr_addr_gray_reg;
  reg [ADDR_WIDTH-1:0] wr_addr_bin_reg;
  reg wr_addr_sync1, wr_addr_sync2;

  // Read side
  reg [ADDR_WIDTH-1:0] rd_addr_gray_reg;
  reg [ADDR_WIDTH-1:0] rd_addr_bin_reg;
  reg rd_addr_sync1, rd_addr_sync2;

  // Sync FIFO pointers
  reg [ADDR_WIDTH-1:0] wr_ptr_gray_d, wr_ptr_gray_q;
  reg [ADDR_WIDTH-1:0] rd_ptr_gray_d, rd_ptr_gray_q;

  // Gray to binary conversion
  function [ADDR_WIDTH-1:0] gray_to_bin;
    input [ADDR_WIDTH-1:0] gray;
    reg [ADDR_WIDTH-1:0] bin;
    integer i;
    bin = 0;
    for (i = ADDR_WIDTH - 1; i >= 0; i = i - 1) begin
      if (i == ADDR_WIDTH - 1)
        bin[i] = gray[i];
      else
        bin[i] = bin[i+1] ^ gray[i];
    end
    return bin;
  endfunction

  // Binary to Gray conversion
  function [ADDR_WIDTH-1:0] bin_to_gray;
    input [ADDR_WIDTH-1:0] bin;
    reg [ADDR_WIDTH-1:0] gray;
    integer i;
    for (i = ADDR_WIDTH - 1; i >= 0; i = i - 1) begin
      if (i == 0)
        gray[i] = bin[i];
      else
        gray[i] = bin[i] ^ bin[i-1];
    end
    return gray;
  endfunction

  // Write clock domain
  always @(posedge wr_clk or negedge wr_rst_n) begin
    if (!wr_rst_n) begin
      wr_addr_bin_reg <= {ADDR_WIDTH{1'b0}};
      wr_addr_gray_reg <= {ADDR_WIDTH{1'b0}};
    end else begin
      if (wr_en) begin
        wr_addr_bin_reg <= wr_addr_bin_reg + 1;
        wr_addr_gray_reg <= bin_to_gray(wr_addr_bin_reg + 1);
      end
    end
  end

  // Read clock domain
  always @(posedge rd_clk or negedge rd_rst_n) begin
    if (!rd_rst_n) begin
      rd_addr_bin_reg <= {ADDR_WIDTH{1'b0}};
      rd_addr_gray_reg <= {ADDR_WIDTH{1'b0}};
    end else begin
      if (rd_en) begin
        rd_addr_bin_reg <= rd_addr_bin_reg + 1;
        rd_addr_gray_reg <= bin_to_gray(rd_addr_bin_reg + 1);
      end
    end
  end

  // Synchronizer for write pointer
  always @(posedge wr_clk or negedge wr_rst_n) begin
    if (!wr_rst_n) begin
      wr_ptr_gray_q <= {ADDR_WIDTH{1'b0}};
    end else begin
      wr_ptr_gray_q <= wr_addr_gray_reg;
    end
  end

  // Synchronizer for read pointer
  always @(posedge rd_clk or negedge rd_rst_n) begin
    if (!rd_rst_n) begin
      rd_ptr_gray_q <= {ADDR_WIDTH{1'b0}};
    end else begin
      rd_ptr_gray_q <= rd_addr_gray_reg;
    end
  end

  // FIFO read/write logic
  reg [7:0] data_out;
  reg fifo_full, fifo_empty;

  always @(posedge wr_clk or negedge wr_rst_n) begin
    if (!wr_rst_n) begin
      fifo_full <= 1'b0;
    end else begin
      if (wr_en && !fifo_full) begin
        fifo_mem[wr_addr_bin_reg] <= wr_data;
      end
    end
  end

  always @(posedge rd_clk or negedge rd_rst_n) begin
    if (!rd_rst_n) begin
      fifo_empty <= 1'b1;
    end else begin
      if (rd_en && !fifo_empty) begin
        data_out <= fifo_mem[rd_addr_bin_reg];
      end
    end
  end

  // Full/empty flags
  assign full = fifo_full;
  assign empty = fifo_empty;

  // Output assignment
  assign rd_data = data_out;

  // Update full/empty flags
  always @(posedge wr_clk or negedge wr_rst_n) begin
    if (!wr_rst_n) begin
      fifo_full <= 1'b0;
      fifo_empty <= 1'b1;
    end else begin
      if (wr_en && !fifo_full) begin
        fifo_full <= (wr_addr_bin_reg == rd_addr_bin_reg);
      end

      if (rd_en && !fifo_empty) begin
        fifo_empty <= (wr_addr_bin_reg == rd_addr_bin_reg);
      end
    end
  end

endmodule

